/* Minimal FASTA/FASTQ reader with buffered streams using zlib.
 * Provides a stream interface similar to kseq but written from scratch.
 */
#ifndef KSEQ_MINI_H
#define KSEQ_MINI_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <zlib.h>

#define BUF_SIZE 16384

typedef struct {
    char *s;
    int l, m;    /* length and max capacity */
} kstring_t;

static inline void ks_put(kstring_t *s, int c) {
    if (s->l + 1 >= s->m) {
        int nm = s->m ? s->m * 2 : 64;
        s->s = (char*)realloc(s->s, nm);
        s->m = nm;
    }
    s->s[s->l++] = c;
    s->s[s->l] = 0;
}

typedef struct {
    gzFile fp;
    unsigned char buf[BUF_SIZE];
    int buf_pos;
    int buf_end;
    int last_char;
    int eof;
    kstring_t name;
    kstring_t comment;
    kstring_t seq;
    kstring_t qual;
} kseq_t;

static kseq_t *kseq_init(gzFile fp) {
    kseq_t *k = (kseq_t*)calloc(1, sizeof(kseq_t));
    k->fp = fp;
    k->last_char = 0;
    return k;
}

static void kseq_destroy(kseq_t *k) {
    if (!k) return;
    free(k->name.s);
    free(k->comment.s);
    free(k->seq.s);
    free(k->qual.s);
    free(k);
}

static int ks_getc(kseq_t *k) {
    if (k->eof && k->buf_pos >= k->buf_end) return -1;
    if (k->buf_pos >= k->buf_end) {
        k->buf_end = gzread(k->fp, k->buf, BUF_SIZE);
        k->buf_pos = 0;
        if (k->buf_end <= 0) { k->eof = 1; return -1; }
    }
    return k->buf[k->buf_pos++];
}

/* Read a line (without newline) appending to s. Returns length read, -1 on EOF before any read. */
static int ks_getline(kseq_t *k, kstring_t *s, int delim) {
    int c, got = 0;
    while (1) {
        if (k->buf_pos >= k->buf_end) {
            if (k->eof) break;
            k->buf_end = gzread(k->fp, k->buf, BUF_SIZE);
            k->buf_pos = 0;
            if (k->buf_end <= 0) { k->eof = 1; break; }
        }
        c = k->buf[k->buf_pos++];
        got = 1;
        if (c == '\n' || (delim != 2 && (delim == 0 ? isspace(c) : c == delim))) {
            if (c == '\n' && s->l > 0 && s->s[s->l-1] == '\r') {
                s->s[--s->l] = 0;
            }
            return s->l;
        }
        ks_put(s, c);
    }
    if (got) return s->l;
    return -1;
}

/* Read next FASTA/FASTQ record. Returns length of seq, -1 on EOF, -2 on malformed */
static int kseq_read(kseq_t *k) {
    int c;
    k->name.l = 0;
    k->comment.l = 0;
    k->seq.l = 0;
    k->qual.l = 0;
    if (k->last_char == 0) {
        while ((c = ks_getc(k)) != -1 && c != '>' && c != '@') ;
        if (c == -1) return -1;
        k->last_char = c;
    }
    /* read name (up to whitespace) */
    while (1) {
        c = ks_getc(k);
        if (c == -1) return -1;
        if (c == '\n') break;
        if (isspace(c)) {
            /* read comment until newline */
            while ((c = ks_getc(k)) != -1 && c != '\n') {
                if (k->comment.l > 0 || !isspace(c))
                    ks_put(&k->comment, c);
            }
            /* trim trailing whitespace/\r */
            while (k->comment.l > 0 && isspace((unsigned char)k->comment.s[k->comment.l-1]))
                k->comment.s[--k->comment.l] = 0;
            break;
        }
        ks_put(&k->name, c);
    }
    /* read seq until + or > or @ */
    while ((c = ks_getc(k)) != -1) {
        if (c == '\n') continue;
        if (c == '>' || c == '+' || c == '@') {
            k->last_char = c;
            break;
        }
        ks_put(&k->seq, c);
        /* Read rest of line */
        while ((c = ks_getc(k)) != -1 && c != '\n') {
            ks_put(&k->seq, c);
        }
    }
    if (c == -1) { k->last_char = 0; return k->seq.l; }
    if (k->last_char == '>' || k->last_char == '@') {
        /* pure FASTA */
        if (k->last_char == k->last_char) {
            /* If we got here with '>' on a FASTQ header line restart, */
        }
        return k->seq.l;
    }
    if (k->last_char == '+') {
        /* skip rest of + line */
        while ((c = ks_getc(k)) != -1 && c != '\n') ;
        /* read quality until same length as seq */
        while (k->qual.l < k->seq.l) {
            c = ks_getc(k);
            if (c == -1) break;
            if (c == '\n') continue;
            ks_put(&k->qual, c);
        }
        k->last_char = 0;
        if (k->qual.l != k->seq.l) return -2;
        return k->seq.l;
    }
    return k->seq.l;
}

#endif
