/* A simple FASTA/FASTQ reader using zlib.
 * Written from scratch, not derived from any existing project.
 */
#ifndef KSEQ_MINI_H
#define KSEQ_MINI_H

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <zlib.h>

#define KS_BUF 16384

typedef struct {
    char *s;
    int l, m;
} kstring_t;

static inline void ks_clear(kstring_t *s) { s->l = 0; if (s->s) s->s[0]=0; }

static inline void ks_put(kstring_t *s, int c) {
    if (s->l + 2 > s->m) {
        int nm = s->m ? s->m * 2 : 64;
        s->s = (char*)realloc(s->s, nm);
        s->m = nm;
    }
    s->s[s->l++] = (char)c;
    s->s[s->l] = 0;
}

typedef struct {
    gzFile fp;
    unsigned char buf[KS_BUF];
    int bp;
    int be;
    int eof;
    int last;   /* last char read; 0 for none */
    kstring_t name;
    kstring_t comment;
    kstring_t seq;
    kstring_t qual;
} kseq_t;

static kseq_t *kseq_init(gzFile fp) {
    kseq_t *k = (kseq_t*)calloc(1, sizeof(kseq_t));
    k->fp = fp;
    return k;
}

static void kseq_destroy(kseq_t *k) {
    if (!k) return;
    free(k->name.s); free(k->comment.s); free(k->seq.s); free(k->qual.s);
    free(k);
}

static int kg_getc(kseq_t *k) {
