/* ---------- Standard random number generator (drand48 family) ---------- */
/* We use the standard libc drand48/srand48 so results are deterministic across runs */

/* ---------- Hash table for names ---------- */
typedef struct khnode {
    char *key;
    int val;
    struct khnode *next;
} khnode;

typedef struct {
    khnode **buckets;
    int n_buckets;
    int n;
} khash_t;

static unsigned int kh_hash(const char *s) {
    unsigned int h = 5381;
    while (*s) { h = ((h << 5) + h) + (unsigned char)*s++; }
    return h;
}

static khash_t *kh_init(int size) {
    khash_t *h = calloc(1, sizeof(khash_t));
    h->n_buckets = size ? size : 1024;
    h->buckets = calloc(h->n_buckets, sizeof(khnode*));
    return h;
}

static void kh_destroy(khash_t *h) {
    if (!h) return;
    for (int i = 0; i < h->n_buckets; ++i) {
        khnode *n = h->buckets[i];
        while (n) { khnode *t = n->next; free(n->key); free(n); n = t; }
    }
    free(h->buckets);
    free(h);
}

static int kh_get(khash_t *h, const char *key) {
    unsigned int idx = kh_hash(key) % h->n_buckets;
    for (khnode *n = h->buckets[idx]; n; n = n->next)
        if (strcmp(n->key, key) == 0) return n->val;
    return -1;
}

static khnode *kh_find(khash_t *h, const char *key) {
    unsigned int idx = kh_hash(key) % h->n_buckets;
    for (khnode *n = h->buckets[idx]; n; n = n->next)
        if (strcmp(n->key, key) == 0) return n;
    return NULL;
}

static void kh_put(khash_t *h, const char *key, int val) {
    unsigned int idx = kh_hash(key) % h->n_buckets;
    for (khnode *n = h->buckets[idx]; n; n = n->next)
        if (strcmp(n->key, key) == 0) { n->val = val; return; }
    khnode *n = malloc(sizeof(khnode));
    n->key = strdup(key);
    n->val = val;
    n->next = h->buckets[idx];
    h->buckets[idx] = n;
    h->n++;
}

/* ---------- BED / name list parsing ---------- */
typedef struct {
    int start;
    int end;
    int strand; /* 0=+, 1=-, -1=unknown */
    char *name;
} bed_reg_t;

typedef struct {
    bed_reg_t *regs;
    int n;
    int m;
} bed_list_t;

typedef struct {
    char *chr;
    bed_list_t list;
} bed_chrom_t;

typedef struct {
    bed_chrom_t *chroms;
    int n, m;
    khash_t *idx; /* chr name -> index into chroms */
    int has_region; /* 0 if only names are provided (name list) */
} bed_t;

static bed_t *bed_init(void) { bed_t *b = calloc(1,sizeof(bed_t)); b->idx = kh_init(0); return b; }

static void bed_free(bed_t *b) {
    if (!b) return;
    for (int i = 0; i < b->n; i++) {
        free(b->chroms[i].chr);
        for (int j = 0; j < b->chroms[i].list.n; j++)
            free(b->chroms[i].list.regs[j].name);
        free(b->chroms[i].list.regs);
    }
    free(b->chroms);
    kh_destroy(b->idx);
    free(b);
}

static bed_chrom_t *bed_get_or_add(bed_t *b, const char *chr) {
    int idx = kh_get(b->idx, chr);
    if (idx >= 0) return &b->chroms[idx];
    if (b->n >= b->m) {
        b->m = b->m ? b->m * 2 : 32;
        b->chroms = realloc(b->chroms, b->m * sizeof(bed_chrom_t));
    }
    memset(&b->chroms[b->n], 0, sizeof(bed_chrom_t));
    b->chroms[b->n].chr = strdup(chr);
    kh_put(b->idx, chr, b->n);
    return &b->chroms[b->n++];
}

static void bed_add_reg(bed_chrom_t *c, int start, int end, int strand, const char *name) {
    if (c->list.n >= c->list.m) {
        c->list.m = c->list.m ? c->list.m * 2 : 8;
        c->list.regs = realloc(c->list.regs, c->list.m * sizeof(bed_reg_t));
    }
    c->list.regs[c->list.n].start = start;
    c->list.regs[c->list.n].end = end;
    c->list.regs[c->list.n].strand = strand;
    c->list.regs[c->list.n].name = name ? strdup(name) : NULL;
    c->list.n++;
}

/* Read a BED/name file. Lines may be:
 *   chr start end [name score strand]
 *   chr
 */
static bed_t *bed_read(const char *fn) {
    gzFile fp = xzopen(fn);
    if (!fp) return NULL;
    bed_t *b = bed_init();
    b->has_region = 0;
    /* read file line by line */
    kstring_t line = {0,0,0};
    unsigned char buf[8192];
    int n, has_any_region = 0;
    line.m = 0; line.s = NULL; line.l = 0;
    while ((n = gzread(fp, buf, sizeof(buf))) > 0) {
        for (int i = 0; i < n; i++) {
            int c = buf[i];
            if (c == '\n' || c == '\r') {
                if (line.l > 0) {
                    /* parse */
                    char *s = line.s;
                    char *tok[6]; int nt = 0;
                    while (nt < 6) {
                        tok[nt++] = s;
                        while (*s && *s != '\t' && *s != ' ') s++;
                        if (*s == 0) break;
                        *s++ = 0;
                    }
                    if (nt >= 1 && tok[0][0] != '#') {
                        bed_chrom_t *cc = bed_get_or_add(b, tok[0]);
                        if (nt >= 3) {
                            int start = atoi(tok[1]);
                            int end = atoi(tok[2]);
                            int strand = -1;
                            const char *name = nt >= 4 ? tok[3] : NULL;
                            if (nt >= 6) {
                                strand = (tok[5][0] == '-') ? 1 : 0;
                            }
                            bed_add_reg(cc, start, end, strand, name);
                            has_any_region = 1;
                        }
                    }
                }
                line.l = 0;
                if (line.s) line.s[0] = 0;
            } else {
                ks_put(&line, c);
            }
        }
    }
    if (line.l > 0) {
        char *s = line.s;
        char *tok[6]; int nt = 0;
        while (nt < 6) {
            tok[nt++] = s;
            while (*s && *s != '\t' && *s != ' ') s++;
            if (*s == 0) break;
            *s++ = 0;
        }
        if (nt >= 1 && tok[0][0] != '#') {
            bed_chrom_t *cc = bed_get_or_add(b, tok[0]);
            if (nt >= 3) {
                int start = atoi(tok[1]);
                int end = atoi(tok[2]);
                int strand = -1;
                const char *name = nt >= 4 ? tok[3] : NULL;
                if (nt >= 6) strand = (tok[5][0] == '-') ? 1 : 0;
                bed_add_reg(cc, start, end, strand, name);
                has_any_region = 1;
            }
        }
    }
    free(line.s);
    gzclose(fp);
    b->has_region = has_any_region;
    return b;
}

