    fprintf(stderr, "         -1        output the 2n-1 reads only\n");
    fprintf(stderr, "         -2        output the 2n reads only\n");
    fprintf(stderr, "         -V        shift quality by '(-Q) - 33'\n");
    fprintf(stderr, "         -U        convert all bases to uppercases\n");
    fprintf(stderr, "         -x        convert all lowercases to -n\n");
    fprintf(stderr, "         -S        strip of white spaces in sequences\n");
    fprintf(stderr, "\n");
    return 1;
}

static int stk_seq(int argc, char **argv) {
    int c;
    int qual_thres = 0;        /* -q */
    int qual_thres_high = 255; /* -X */
    int mask_char = 0;         /* -n: 0 for lowercase */
    int line_len = 0;
    int qual_shift = 33;
    unsigned seed = 11;
    double frac = 1.0;
    char *mask_file = NULL;
    int min_len = 0;
    int fake_q = 0;            /* -F */
    int flag = 0;
    /* bits: 1=A 2=C 4=r 8=R 16=N 32=1 64=2 128=V 256=U 512=x 1024=S 2048=C(drop comment) 4096=mask_complement(-c) */
    int mode_seq_only = 0;
    (void)mode_seq_only;

    optind = 1;
    while ((c = getopt(argc, argv, "q:X:n:l:Q:s:f:M:L:F:crRACN12VUxS")) >= 0) {
        switch (c) {
        case 'q': qual_thres = atoi(optarg); break;
        case 'X': qual_thres_high = atoi(optarg); break;
        case 'n': mask_char = optarg[0]; break;
        case 'l': line_len = atoi(optarg); break;
        case 'Q': qual_shift = atoi(optarg); break;
        case 's': seed = (unsigned)atoi(optarg); break;
        case 'f': frac = atof(optarg); break;
        case 'M': mask_file = optarg; break;
        case 'L': min_len = atoi(optarg); break;
        case 'F': fake_q = optarg[0]; break;
        case 'c': flag |= 4096; break;
        case 'r': flag |= 4; break;
        case 'R': flag |= 8; break;
        case 'A': flag |= 1; break;
        case 'C': flag |= 2048; break;
        case 'N': flag |= 16; break;
        case '1': flag |= 32; break;
        case '2': flag |= 64; break;
        case 'V': flag |= 128; break;
        case 'U': flag |= 256; break;
        case 'x': flag |= 512; break;
        case 'S': flag |= 1024; break;
        default: return 1;
        }
    }
    if (argc == optind && isatty(fileno(stdin))) return usage_seq();

    bed_t *mask = NULL;
    if (mask_file) {
        mask = bed_read(mask_file);
    }

    /* seed RNG */
    srand48(seed);

    gzFile fp = xzopen(argc > optind ? argv[optind] : NULL);
    if (!fp) {
        fprintf(stderr, "[E::stk_seq] failed to open the input file/stream.\n");
        return 1;
    }
    kseq_t *ks = kseq_init(fp);
    int rec_idx = 0;
    while (kseq_read(ks) >= 0) {
        rec_idx++;
        /* 1/2 filter */
        if ((flag & 32) && (rec_idx % 2 == 0)) continue;
        if ((flag & 64) && (rec_idx % 2 == 1)) continue;

        /* fraction sample */
        if (frac < 1.0) {
            if (drand48() >= frac) continue;
        }

        int has_qual = ks->qual.l > 0;
        if (!has_qual && fake_q) {
            /* fake FASTQ output */
            ks->qual.l = 0;
            for (int i = 0; i < ks->seq.l; i++) ks_put(&ks->qual, fake_q);
            has_qual = 1;
        }

        /* quality shift */
        if ((flag & 128) && has_qual) {
            int sh = (-qual_shift) - 33;
            (void)sh;
            int delta = 33 - qual_shift;
            for (int i = 0; i < ks->qual.l; i++)
                ks->qual.s[i] = (char)(ks->qual.s[i] + delta);
            /* adjust qual_shift for subsequent masking? */
            /* After V, quality treated as base 33 */
        }

        /* strip whitespace from sequence (note: replicates the original tool's behaviour
         * where the string is rewritten in-place but the original length is preserved).
         */
        if (flag & 1024) {
            int j = 0;
            for (int i = 0; i < ks->seq.l; i++)
                if (!isspace((unsigned char)ks->seq.s[i]))
                    ks->seq.s[j++] = ks->seq.s[i];
            /* original seqtk does not update length; bug preserved for compatibility */
            /* Do same for qual */
            if (has_qual) {
                int k = 0;
                for (int i = 0; i < ks->qual.l; i++)
                    if (!isspace((unsigned char)ks->qual.s[i]))
                        ks->qual.s[k++] = ks->qual.s[i];
            }
        }

        /* uppercase */
        if (flag & 256) {
            for (int i = 0; i < ks->seq.l; i++)
                ks->seq.s[i] = toupper((unsigned char)ks->seq.s[i]);
        }

        /* min length filter */
        if (min_len > 0 && ks->seq.l < min_len) continue;

        /* N filter */
        if (flag & 16) {
            int found = 0;
            for (int i = 0; i < ks->seq.l; i++) {
                int ch = toupper((unsigned char)ks->seq.s[i]);
                if (ch != 'A' && ch != 'C' && ch != 'G' && ch != 'T' && ch != 'U') { found = 1; break; }
            }
            if (found) continue;
        }

        /* quality masking */
        int eff_shift = (flag & 128) ? 33 : qual_shift;
        if (has_qual && (qual_thres > 0 || qual_thres_high < 255)) {
            for (int i = 0; i < ks->qual.l && i < ks->seq.l; i++) {
                int q = (unsigned char)ks->qual.s[i] - eff_shift;
                if (q < qual_thres || q > qual_thres_high) {
                    if (mask_char == 0) ks->seq.s[i] = tolower((unsigned char)ks->seq.s[i]);
                    else ks->seq.s[i] = (char)mask_char;
                }
            }
        }

        /* BED masking */
        if (mask) {
            int mask_comp = (flag & 4096) != 0;
            bed_chrom_t *cc = NULL;
            int idx = kh_get(mask->idx, ks->name.s);
            if (idx >= 0) cc = &mask->chroms[idx];
            if (!mask_comp) {
                if (cc) {
                    for (int r = 0; r < cc->list.n; r++) {
                        int s = cc->list.regs[r].start;
                        int e = cc->list.regs[r].end;
                        if (s < 0) s = 0;
                        if (e > ks->seq.l) e = ks->seq.l;
                        for (int i = s; i < e; i++) {
                            if (mask_char == 0) ks->seq.s[i] = tolower((unsigned char)ks->seq.s[i]);
                            else ks->seq.s[i] = (char)mask_char;
                        }
                    }
                }
            } else {
                /* mask complement: mask positions NOT in any region */
                char *msk = calloc(ks->seq.l, 1);
                if (cc) {
                    for (int r = 0; r < cc->list.n; r++) {
                        int s = cc->list.regs[r].start;
                        int e = cc->list.regs[r].end;
                        if (s < 0) s = 0;
                        if (e > ks->seq.l) e = ks->seq.l;
                        for (int i = s; i < e; i++) msk[i] = 1;
                    }
                }
                for (int i = 0; i < ks->seq.l; i++) {
                    if (!msk[i]) {
                        if (mask_char == 0) ks->seq.s[i] = tolower((unsigned char)ks->seq.s[i]);
                        else ks->seq.s[i] = (char)mask_char;
                    }
                }
                free(msk);
            }
        }

        /* convert lowercase to -n mask char */
        if (flag & 512) {
            int mc = mask_char ? mask_char : 'N';
            for (int i = 0; i < ks->seq.l; i++) {
                unsigned char uc = ks->seq.s[i];
                if (islower(uc)) ks->seq.s[i] = (char)mc;
            }
        }

        int force_fa = (flag & 1) != 0;
        int drop_comment = (flag & 2048) != 0;

        /* reverse complement function */
        void do_rc(char *seq, char *qual, int l) {
            for (int i = 0; i < l / 2; i++) {
                char a = seq[i], b = seq[l-1-i];
                seq[i] = comp_tab[(unsigned char)b];
                seq[l-1-i] = comp_tab[(unsigned char)a];
                if (qual) { char t = qual[i]; qual[i] = qual[l-1-i]; qual[l-1-i] = t; }
            }
            if (l & 1) seq[l/2] = comp_tab[(unsigned char)seq[l/2]];
        }

        /* output */
        char header_char = (has_qual && !force_fa) ? '@' : '>';

        int outputs = 1;
        if (flag & 8) outputs = 2; /* both strands */

        for (int oi = 0; oi < outputs; oi++) {
            int is_rev = 0;
            if (flag & 4) is_rev = 1;
            if (flag & 8) is_rev = (oi == 1);

            if (is_rev) do_rc(ks->seq.s, has_qual && !force_fa ? ks->qual.s : NULL, ks->seq.l);

            putchar(header_char);
            fwrite(ks->name.s, 1, ks->name.l, stdout);
            if (flag & 8) {
                /* append +/- */
                putchar(oi == 0 ? '+' : '-');
            }
            if (!drop_comment && ks->comment.l > 0) {
                putchar(' ');
                fwrite(ks->comment.s, 1, ks->comment.l, stdout);
            }
            putchar('\n');
            print_seq_folded(ks->seq.s, ks->seq.l, line_len);
            if (has_qual && !force_fa) {
                puts("+");
                print_seq_folded(ks->qual.s, ks->seq.l, line_len);
            }

            if (is_rev && (flag & 8)) {
                /* revert back so next iteration starts with forward */
                do_rc(ks->seq.s, has_qual && !force_fa ? ks->qual.s : NULL, ks->seq.l);
            }
        }
    }
    kseq_destroy(ks);
    gzclose(fp);
    if (mask) bed_free(mask);
    return 0;
}

