}

/* ---------- size ---------- */
static int stk_size(int argc, char **argv) {
    if (argc < 2) {
        /* read from stdin */
    }
    gzFile fp = xzopen(argc > 1 ? argv[1] : NULL);
    if (!fp) {
        fprintf(stderr, "[E::stk_size] failed to open the input file/stream.\n");
        return 1;
    }
    kseq_t *ks = kseq_init(fp);
    long long n_seq = 0, n_bp = 0;
    while (kseq_read(ks) >= 0) { n_seq++; n_bp += ks->seq.l; }
    kseq_destroy(ks); gzclose(fp);
    printf("%lld\t%lld\n", n_seq, n_bp);
    return 0;
}

/* ---------- comp ---------- */
static void comp_region(const char *chr, const char *s, int slen, int start, int end, int to_upper) {
    if (start < 0) start = 0;
    if (end > slen) end = slen;
    int cnt[128] = {0};
    int transitions = 0, transversions = 0, cpg = 0, cpg_ts = 0;
    int a = 0, c = 0, g = 0, t = 0, n = 0;
    int dimer[5][5] = {{0}};
    (void)dimer;
    for (int i = start; i < end; i++) {
        int ch = s[i];
        if (to_upper) ch = toupper((unsigned char)ch);
        cnt[(unsigned char)ch]++;
    }
    /* Count A,C,G,T; ambiguous letters split contribution. */
    /* seqtk comp counts bases that "resolve" to combinations.
     * Columns: chr, length, #A, #C, #G, #T, #2, #3, #4, #CpG, #tv, #ts, #CpG-ts
     * Where #2, #3, #4 are counts of 2-way, 3-way, 4-way ambiguous codes
     * And #CpG is count of CG dinucleotides, #tv transversions?, #ts transitions in some sense
     */
    a = cnt[(unsigned char)'A'] + cnt[(unsigned char)'a'];
    c = cnt[(unsigned char)'C'] + cnt[(unsigned char)'c'];
    g = cnt[(unsigned char)'G'] + cnt[(unsigned char)'g'];
    t = cnt[(unsigned char)'T'] + cnt[(unsigned char)'t'];
    (void)n;
    /* 2-way codes: M R W S Y K */
    int c2 = 0;
    const char *two = "MRWSYKmrwsyk";
    for (const char *p = two; *p; p++) c2 += cnt[(unsigned char)*p];
    /* 3-way: B D H V */
    int c3 = 0;
    const char *three = "BDHVbdhv";
    for (const char *p = three; *p; p++) c3 += cnt[(unsigned char)*p];
    /* 4-way: N and others */
    int c4 = 0;
    c4 += cnt[(unsigned char)'N'] + cnt[(unsigned char)'n'];
    /* CpG count: dinucleotide 'CG' (case-insensitive) */
    int cpg_count = 0;
    for (int i = start; i < end - 1; i++) {
        int x = toupper((unsigned char)s[i]);
        int y = toupper((unsigned char)s[i+1]);
        if (x == 'C' && y == 'G') cpg_count++;
    }
    (void)transitions; (void)transversions; (void)cpg; (void)cpg_ts;
    int cpg_col = cpg_count;
    /* In absence of SNP info we can only output basic stats */
    if (start == 0 && end == slen) {
        /* whole-sequence format (no start/end in output) */
        printf("%s\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\n",
               chr, slen, a, c, g, t, c2, c3, c4, cpg_col, 0, 0, 0);
    } else {
        printf("%s\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\t%d\n",
               chr, start, end, end - start, a, c, g, t, c2, c3, c4, cpg_col, 0, 0, 0);
    }
}

static int stk_comp(int argc, char **argv) {
    int c;
    int to_upper = 0;
    char *bed_fn = NULL;
    optind = 1;
    while ((c = getopt(argc, argv, "ur:")) >= 0) {
        if (c == 'u') to_upper = 1;
        else if (c == 'r') bed_fn = optarg;
    }
    if (argc == optind && isatty(fileno(stdin))) {
        fprintf(stderr, "Usage:  seqtk comp [-u] [-r in.bed] <in.fa>\n\n");
        fprintf(stderr, "Output format: chr, length, #A, #C, #G, #T, #2, #3, #4, #CpG, #tv, #ts, #CpG-ts\n");
        return 1;
    }
    bed_t *bed = NULL;
    if (bed_fn) bed = bed_read(bed_fn);
    gzFile fp = xzopen(argc > optind ? argv[optind] : NULL);
    if (!fp) {
        fprintf(stderr, "[E::stk_comp] failed to open the input file/stream.\n");
        return 1;
    }
    kseq_t *ks = kseq_init(fp);
    while (kseq_read(ks) >= 0) {
        if (bed) {
            int idx = kh_get(bed->idx, ks->name.s);
            if (idx < 0) continue;
            bed_chrom_t *cc = &bed->chroms[idx];
            for (int r = 0; r < cc->list.n; r++)
                comp_region(ks->name.s, ks->seq.s, ks->seq.l, cc->list.regs[r].start, cc->list.regs[r].end, to_upper);
        } else {
            comp_region(ks->name.s, ks->seq.s, ks->seq.l, 0, ks->seq.l, to_upper);
        }
    }
    kseq_destroy(ks); gzclose(fp);
    if (bed) bed_free(bed);
    return 0;
}

