/* ---------- sample ---------- */
static int stk_sample(int argc, char **argv) {
    int c;
    unsigned seed = 11;
    int two_pass = 0;
    optind = 1;
    while ((c = getopt(argc, argv, "s:2")) >= 0) {
        if (c == 's') seed = (unsigned)atoi(optarg);
        else if (c == '2') two_pass = 1;
    }
    if (optind + 2 > argc) {
        fprintf(stderr, "\nUsage:   seqtk sample [-2] [-s seed=11] <in.fa> <frac>|<number>\n\n");
        fprintf(stderr, "Options: -s INT       RNG seed [11]\n");
        fprintf(stderr, "         -2           2-pass mode: twice as slow but with much reduced memory\n\n");
        return 1;
    }
    double frac = atof(argv[optind+1]);
    long num = frac > 1 ? (long)frac : 0;
    srand48(seed);
    const char *fn = argv[optind];

    if (num == 0) {
        /* fraction mode */
        if (two_pass) {
            fprintf(stderr, "[W::stk_sample] when sampling a fraction, option -2 is ignored.");
        }
        gzFile fp = xzopen(fn);
        if (!fp) { fprintf(stderr, "[E::stk_sample] failed to open the input file/stream.\n"); return 1; }
        kseq_t *ks = kseq_init(fp);
        while (kseq_read(ks) >= 0) {
            double r = drand48();
            if (r < frac) {
                int has_qual = ks->qual.l > 0;
                putchar(has_qual ? '@' : '>');
                fwrite(ks->name.s, 1, ks->name.l, stdout);
                if (ks->comment.l) { putchar(' '); fwrite(ks->comment.s, 1, ks->comment.l, stdout); }
                putchar('\n');
                fwrite(ks->seq.s, 1, ks->seq.l, stdout); putchar('\n');
                if (has_qual) { puts("+"); fwrite(ks->qual.s, 1, ks->qual.l, stdout); putchar('\n'); }
            }
        }
        kseq_destroy(ks); gzclose(fp);
        return 0;
    }

    if (two_pass) {
        if (strcmp(fn, "-") == 0) {
            fprintf(stderr, "[E::stk_sample] in the 2-pass mode, the input cannot be STDIN.\n");
            return 1;
        }
        /* first pass: count sequences */
        gzFile fp = xzopen(fn);
        if (!fp) { fprintf(stderr, "[E::stk_sample] failed to open the input file/stream.\n"); return 1; }
        kseq_t *ks = kseq_init(fp);
        long total = 0;
        while (kseq_read(ks) >= 0) total++;
        kseq_destroy(ks); gzclose(fp);

        /* Generate num random indices from [0, total) without replacement using rejection */
        long picks_n = num < total ? num : total;
        char *selected = calloc(total, 1);
        long chosen = 0;
        while (chosen < picks_n) {
            long idx = (long)(drand48() * total);
            if (idx >= total) idx = total - 1;
            if (!selected[idx]) { selected[idx] = 1; chosen++; }
        }

        fp = xzopen(fn);
        ks = kseq_init(fp);
        long i = 0;
        while (kseq_read(ks) >= 0) {
            if (i < total && selected[i]) {
                int has_qual = ks->qual.l > 0;
                putchar(has_qual ? '@' : '>');
                fwrite(ks->name.s, 1, ks->name.l, stdout);
                if (ks->comment.l) { putchar(' '); fwrite(ks->comment.s, 1, ks->comment.l, stdout); }
                putchar('\n');
                fwrite(ks->seq.s, 1, ks->seq.l, stdout); putchar('\n');
                if (has_qual) { puts("+"); fwrite(ks->qual.s, 1, ks->qual.l, stdout); putchar('\n'); }
            }
            i++;
        }
        kseq_destroy(ks); gzclose(fp);
        free(selected);
        return 0;
    }

    /* Reservoir sampling */
    gzFile fp = xzopen(fn);
    if (!fp) { fprintf(stderr, "[E::stk_sample] failed to open the input file/stream.\n"); return 1; }
    kseq_t *ks = kseq_init(fp);

    typedef struct { char *name, *comment, *seq, *qual; int sl, ql; } rec_t;
    rec_t *reservoir = calloc(num, sizeof(rec_t));
    long i = 0;
    while (kseq_read(ks) >= 0) {
        long pos = -1;
        if (i < num) pos = i;
        else {
            long r = (long)(drand48() * (i + 1));
            if (r < num) pos = r;
        }
        if (pos >= 0) {
            if (reservoir[pos].name) free(reservoir[pos].name);
            if (reservoir[pos].comment) free(reservoir[pos].comment);
            if (reservoir[pos].seq) free(reservoir[pos].seq);
            if (reservoir[pos].qual) free(reservoir[pos].qual);
            reservoir[pos].name = strdup(ks->name.s ? ks->name.s : "");
            reservoir[pos].comment = ks->comment.l ? strdup(ks->comment.s) : NULL;
            reservoir[pos].seq = malloc(ks->seq.l + 1);
            memcpy(reservoir[pos].seq, ks->seq.s, ks->seq.l); reservoir[pos].seq[ks->seq.l] = 0;
            reservoir[pos].sl = ks->seq.l;
            if (ks->qual.l) {
                reservoir[pos].qual = malloc(ks->qual.l + 1);
                memcpy(reservoir[pos].qual, ks->qual.s, ks->qual.l); reservoir[pos].qual[ks->qual.l] = 0;
                reservoir[pos].ql = ks->qual.l;
            } else { reservoir[pos].qual = NULL; reservoir[pos].ql = 0; }
        }
        i++;
    }
    long outn = i < num ? i : num;
    for (long k = 0; k < outn; k++) {
        int has_qual = reservoir[k].ql > 0;
        putchar(has_qual ? '@' : '>');
        fputs(reservoir[k].name, stdout);
        if (reservoir[k].comment) { putchar(' '); fputs(reservoir[k].comment, stdout); }
        putchar('\n');
        fwrite(reservoir[k].seq, 1, reservoir[k].sl, stdout); putchar('\n');
        if (has_qual) { puts("+"); fwrite(reservoir[k].qual, 1, reservoir[k].ql, stdout); putchar('\n'); }
        free(reservoir[k].name); free(reservoir[k].comment); free(reservoir[k].seq); free(reservoir[k].qual);
    }
    free(reservoir);
    kseq_destroy(ks); gzclose(fp);
    return 0;
}

