/* ---------- subseq ---------- */
static int stk_subseq(int argc, char **argv) {
    int c;
    int tab = 0, strand_aware = 0, line_len = 0;
    optind = 1;
    while ((c = getopt(argc, argv, "tsl:")) >= 0) {
        if (c == 't') tab = 1;
        else if (c == 's') strand_aware = 1;
        else if (c == 'l') line_len = atoi(optarg);
    }
    if (argc - optind < 2) {
        fprintf(stderr, "Usage:   seqtk subseq [options] <in.fa> <in.bed>|<name.list>\n");
        fprintf(stderr, "Options:\n");
        fprintf(stderr, "  -t       TAB delimited output\n");
        fprintf(stderr, "  -s       strand aware\n");
        fprintf(stderr, "  -l INT   sequence line length [0]\n");
        fprintf(stderr, "Note: Use 'samtools faidx' if only a few regions are intended.\n");
        return 1;
    }
    bed_t *bed = bed_read(argv[optind + 1]);
    if (!bed) { fprintf(stderr, "[E::stk_subseq] failed to open the input file/stream.\n"); return 1; }
    gzFile fp = xzopen(argv[optind]);
    if (!fp) { fprintf(stderr, "[E::stk_subseq] failed to open the input file/stream.\n"); return 1; }
    kseq_t *ks = kseq_init(fp);
    while (kseq_read(ks) >= 0) {
        int idx = kh_get(bed->idx, ks->name.s);
        if (idx < 0) continue;
        bed_chrom_t *cc = &bed->chroms[idx];
        int has_qual = ks->qual.l > 0;
        if (cc->list.n == 0) {
            /* name only - output whole sequence */
            if (tab) {
                printf("%s\t0\t", ks->name.s);
                fwrite(ks->seq.s, 1, ks->seq.l, stdout);
                if (has_qual) { putchar('\t'); fwrite(ks->qual.s, 1, ks->qual.l, stdout); }
                putchar('\n');
            } else {
                putchar(has_qual ? '@' : '>');
                fwrite(ks->name.s, 1, ks->name.l, stdout);
                if (ks->comment.l) { putchar(' '); fwrite(ks->comment.s, 1, ks->comment.l, stdout); }
                putchar('\n');
                print_seq_folded(ks->seq.s, ks->seq.l, line_len);
                if (has_qual) { puts("+"); print_seq_folded(ks->qual.s, ks->seq.l, line_len); }
            }
        } else {
            for (int r = 0; r < cc->list.n; r++) {
                int s = cc->list.regs[r].start;
                int e = cc->list.regs[r].end;
                if (s < 0) s = 0;
                if (e > ks->seq.l) e = ks->seq.l;
                int len = e - s;
                if (len < 0) len = 0;
                char *sub = malloc(len + 1);
                char *qsub = has_qual ? malloc(len + 1) : NULL;
                for (int i = 0; i < len; i++) sub[i] = ks->seq.s[s + i];
                sub[len] = 0;
                if (qsub) { for (int i = 0; i < len; i++) qsub[i] = ks->qual.s[s + i]; qsub[len] = 0; }
                if (strand_aware && cc->list.regs[r].strand == 1) {
                    seq_rc_inplace(sub, qsub, len);
                }
                if (tab) {
                    printf("%s\t%d\t", ks->name.s, s);
                    fwrite(sub, 1, len, stdout);
                    if (has_qual) { putchar('\t'); fwrite(qsub, 1, len, stdout); }
                    putchar('\n');
                } else {
                    putchar(has_qual ? '@' : '>');
                    printf("%s:%d-%d", ks->name.s, s + 1, e);
                    putchar('\n');
                    print_seq_folded(sub, len, line_len);
                    if (has_qual) { puts("+"); print_seq_folded(qsub, len, line_len); }
                }
                free(sub); free(qsub);
            }
        }
    }
    kseq_destroy(ks); gzclose(fp);
    bed_free(bed);
    return 0;
}

