/* ---------- fqchk ---------- */
static int stk_fqchk(int argc, char **argv) {
    int c;
    int qthres = 20;
    optind = 1;
    while ((c = getopt(argc, argv, "q:")) >= 0) {
        if (c == 'q') qthres = atoi(optarg);
    }
    if (argc == optind && isatty(fileno(stdin))) {
        fprintf(stderr, "Usage: seqtk fqchk [-q 20] <in.fq>\n");
        fprintf(stderr, "Note: use -q0 to get the distribution of all quality values\n");
        return 1;
    }
    gzFile fp = xzopen(argc > optind ? argv[optind] : NULL);
    if (!fp) { fprintf(stderr, "[E::stk_fqchk] failed to open the input file/stream.\n"); return 1; }
    kseq_t *ks = kseq_init(fp);

    /* Accumulate per-position statistics */
    int max_len = 0;
    /* counts[pos][A..] and qual[pos][q] */
    int cap = 512;
    int **cnt = calloc(cap, sizeof(int*));
    for (int i = 0; i < cap; i++) cnt[i] = calloc(128 + 100, sizeof(int));
    /* Layout: 0..127 = base count (ASCII), 128..227 = qual count */
    int min_len = 0x7fffffff, max_l = 0;
    long long total_len = 0;
    long long n_seq = 0;
    int qual_set[256] = {0};

    while (kseq_read(ks) >= 0) {
        if (ks->qual.l == 0) continue;
        if (ks->seq.l != ks->qual.l) continue;
        n_seq++;
        total_len += ks->seq.l;
        if (ks->seq.l < min_len) min_len = ks->seq.l;
        if (ks->seq.l > max_l) max_l = ks->seq.l;
        if (ks->seq.l > max_len) max_len = ks->seq.l;
        while (max_len >= cap) {
            int oldc = cap; cap *= 2;
            cnt = realloc(cnt, cap * sizeof(int*));
            for (int i = oldc; i < cap; i++) cnt[i] = calloc(128 + 100, sizeof(int));
        }
        for (int i = 0; i < ks->seq.l; i++) {
            unsigned char b = toupper((unsigned char)ks->seq.s[i]);
            cnt[i][b]++;
            int q = (unsigned char)ks->qual.s[i] - 33;
            if (q < 0) q = 0;
            if (q > 99) q = 99;
            cnt[i][128 + q]++;
            qual_set[q] = 1;
        }
    }
    if (n_seq == 0) {
        kseq_destroy(ks); gzclose(fp);
        for (int i = 0; i < cap; i++) free(cnt[i]);
        free(cnt);
        return 0;
    }
    int n_qual = 0;
    for (int i = 0; i < 256; i++) if (qual_set[i]) n_qual++;
    fprintf(stdout, "min_len: %d; max_len: %d; avg_len: %.2f; %d distinct quality values\n",
            min_len, max_l, (double)total_len / n_seq, n_qual);

    if (qthres == 0) {
        /* distribution columns */
        fprintf(stdout, "POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ");
        int qlist[100], nq=0;
        for (int i = 0; i < 100; i++) if (qual_set[i]) qlist[nq++] = i;
        for (int i = 0; i < nq; i++) fprintf(stdout, "\t%%Q%d", qlist[i]);
        fprintf(stdout, "\n");
        /* ALL row */
        long long n_bases = 0;
        long long nA=0, nC=0, nG=0, nT=0, nN=0;
        long long qs = 0; double errs = 0;
        long long qcnt[100] = {0};
        for (int p = 0; p < max_l; p++) {
            nA += cnt[p]['A']; nC += cnt[p]['C']; nG += cnt[p]['G']; nT += cnt[p]['T']; nN += cnt[p]['N'];
            long long tot = 0;
            for (int q = 0; q < 100; q++) { tot += cnt[p][128+q]; qcnt[q] += cnt[p][128+q]; }
            for (int q = 0; q < 100; q++) {
                qs += (long long)q * cnt[p][128+q];
                double e = pow(10.0, -q/10.0);
                if (e > 0.5) e = 0.5;
                errs += e * cnt[p][128+q];
            }
            n_bases += tot;
        }
        if (n_bases > 0) {
            double avgQ = (double)qs / n_bases;
            double errQ = -10.0 * log10(errs / n_bases);
            fprintf(stdout, "ALL\t%lld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f",
                    n_bases,
                    100.0 * nA / n_bases, 100.0 * nC / n_bases,
                    100.0 * nG / n_bases, 100.0 * nT / n_bases,
                    100.0 * nN / n_bases, avgQ, errQ);
            for (int i = 0; i < nq; i++) {
                fprintf(stdout, "\t%.2f", 100.0 * qcnt[qlist[i]] / n_bases);
            }
            fprintf(stdout, "\n");
        }
        /* Per-position */
        for (int p = 0; p < max_l; p++) {
            long long tot = 0;
            long long A = cnt[p]['A'], C = cnt[p]['C'], G = cnt[p]['G'], T = cnt[p]['T'], N = cnt[p]['N'];
            long long qsi = 0; double errsi = 0;
            long long qcnti[100] = {0};
            for (int q = 0; q < 100; q++) { tot += cnt[p][128+q]; qcnti[q] += cnt[p][128+q]; qsi += (long long)q * cnt[p][128+q]; double e = pow(10.0, -q/10.0); if (e > 0.5) e = 0.5; errsi += e * cnt[p][128+q]; }
            if (tot == 0) continue;
            double avgQ = (double)qsi / tot;
            double errQ = -10.0 * log10(errsi / tot);
            fprintf(stdout, "%d\t%lld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f",
                    p+1, tot,
                    100.0*A/tot, 100.0*C/tot, 100.0*G/tot, 100.0*T/tot, 100.0*N/tot,
                    avgQ, errQ);
            for (int i = 0; i < nq; i++)
                fprintf(stdout, "\t%.2f", 100.0 * qcnti[qlist[i]] / tot);
            fprintf(stdout, "\n");
        }
    } else {
        /* Low/High split at qthres */
        fprintf(stdout, "POS\t#bases\t%%A\t%%C\t%%G\t%%T\t%%N\tavgQ\terrQ\t%%low\t%%high\n");
        long long n_bases = 0, nA=0, nC=0, nG=0, nT=0, nN=0;
        long long qs = 0; double errs = 0;
        long long nlow = 0, nhigh = 0;
        for (int p = 0; p < max_l; p++) {
            nA += cnt[p]['A']; nC += cnt[p]['C']; nG += cnt[p]['G']; nT += cnt[p]['T']; nN += cnt[p]['N'];
            for (int q = 0; q < 100; q++) {
                long long c = cnt[p][128+q]; n_bases += c;
                qs += (long long)q * c;
                double e = pow(10.0, -q/10.0); if (e > 0.5) e = 0.5;
                errs += e * c;
                if (q < qthres) nlow += c; else nhigh += c;
            }
        }
        if (n_bases > 0) {
            double avgQ = (double)qs / n_bases;
            double errQ = -10.0 * log10(errs / n_bases);
            fprintf(stdout, "ALL\t%lld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
                n_bases,
                100.0*nA/n_bases,100.0*nC/n_bases,100.0*nG/n_bases,100.0*nT/n_bases,100.0*nN/n_bases,
                avgQ, errQ,
                100.0*nlow/n_bases, 100.0*nhigh/n_bases);
        }
        for (int p = 0; p < max_l; p++) {
            long long tot = 0, A=cnt[p]['A'], C=cnt[p]['C'], G=cnt[p]['G'], T=cnt[p]['T'], N=cnt[p]['N'];
            long long qsi = 0; double errsi = 0; long long nlowi=0, nhighi=0;
            for (int q = 0; q < 100; q++) {
                long long c = cnt[p][128+q]; tot += c;
                qsi += (long long)q * c;
                double e = pow(10.0, -q/10.0); if (e > 0.5) e = 0.5; errsi += e * c;
                if (q < qthres) nlowi += c; else nhighi += c;
            }
            if (tot == 0) continue;
            double avgQ = (double)qsi/tot, errQ = -10.0*log10(errsi/tot);
            fprintf(stdout, "%d\t%lld\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\t%.1f\n",
                p+1, tot,
                100.0*A/tot,100.0*C/tot,100.0*G/tot,100.0*T/tot,100.0*N/tot,
                avgQ, errQ,
                100.0*nlowi/tot, 100.0*nhighi/tot);
        }
    }

    for (int i = 0; i < cap; i++) free(cnt[i]);
    free(cnt);
    kseq_destroy(ks); gzclose(fp);
    return 0;
}

