/* ---------- mergepe ---------- */
static int stk_mergepe(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage: seqtk mergepe <in1.fq> <in2.fq>\n");
        return 1;
    }
    gzFile f1 = xzopen(argv[1]);
    gzFile f2 = xzopen(argv[2]);
    if (!f1 || !f2) { fprintf(stderr, "[E::stk_mergepe] failed to open the input file/stream.\n"); return 1; }
    kseq_t *k1 = kseq_init(f1), *k2 = kseq_init(f2);
    while (1) {
        int r1 = kseq_read(k1);
        int r2 = kseq_read(k2);
        if (r1 < 0 || r2 < 0) break;
        for (int side = 0; side < 2; side++) {
            kseq_t *k = side == 0 ? k1 : k2;
            int has_qual = k->qual.l > 0;
            putchar(has_qual ? '@' : '>');
            fwrite(k->name.s, 1, k->name.l, stdout);
            if (k->comment.l) { putchar(' '); fwrite(k->comment.s, 1, k->comment.l, stdout); }
            putchar('\n');
            fwrite(k->seq.s, 1, k->seq.l, stdout); putchar('\n');
            if (has_qual) { puts("+"); fwrite(k->qual.s, 1, k->qual.l, stdout); putchar('\n'); }
        }
    }
    kseq_destroy(k1); kseq_destroy(k2);
    gzclose(f1); gzclose(f2);
    return 0;
}

/* ---------- dropse ---------- */
static int stk_dropse(int argc, char **argv) {
    if (argc == 1 && isatty(fileno(stdin))) {
        fprintf(stderr, "Usage: seqtk dropse <in.fq>\n");
        return 1;
    }
    gzFile fp = xzopen(argc > 1 ? argv[1] : NULL);
    if (!fp) { fprintf(stderr, "[E::stk_dropse] failed to open the input file/stream.\n"); return 1; }
    kseq_t *ks = kseq_init(fp);
    /* store previous */
    typedef struct { char *name, *comment, *seq, *qual; int sl, ql; char head; } rec_t;
    rec_t prev = {0};
    while (kseq_read(ks) >= 0) {
        int has_qual = ks->qual.l > 0;
        if (prev.name) {
            /* compare name prefixes up to /1, /2, or end */
            int l1 = strlen(prev.name);
            int l2 = ks->name.l;
            /* Strip trailing /1 /2 .1 .2 */
            int a = l1, b = l2;
            if (a >= 2 && prev.name[a-2] == '/') a -= 2;
            if (b >= 2 && ks->name.s[b-2] == '/') b -= 2;
            int same = (a == b && memcmp(prev.name, ks->name.s, a) == 0);
            if (same) {
                /* output prev then curr */
                putchar(prev.ql > 0 ? '@' : '>');
                fputs(prev.name, stdout);
                if (prev.comment) { putchar(' '); fputs(prev.comment, stdout); }
                putchar('\n');
                fwrite(prev.seq, 1, prev.sl, stdout); putchar('\n');
                if (prev.ql > 0) { puts("+"); fwrite(prev.qual, 1, prev.ql, stdout); putchar('\n'); }

                putchar(has_qual ? '@' : '>');
                fwrite(ks->name.s, 1, ks->name.l, stdout);
                if (ks->comment.l) { putchar(' '); fwrite(ks->comment.s, 1, ks->comment.l, stdout); }
                putchar('\n');
                fwrite(ks->seq.s, 1, ks->seq.l, stdout); putchar('\n');
                if (has_qual) { puts("+"); fwrite(ks->qual.s, 1, ks->qual.l, stdout); putchar('\n'); }

                free(prev.name); free(prev.comment); free(prev.seq); free(prev.qual);
                memset(&prev, 0, sizeof(prev));
                continue;
            }
            /* prev was unpaired, drop */
            free(prev.name); free(prev.comment); free(prev.seq); free(prev.qual);
            memset(&prev, 0, sizeof(prev));
        }
        /* store current as prev */
        prev.name = strdup(ks->name.s);
        prev.comment = ks->comment.l ? strdup(ks->comment.s) : NULL;
        prev.seq = malloc(ks->seq.l + 1); memcpy(prev.seq, ks->seq.s, ks->seq.l); prev.seq[ks->seq.l]=0; prev.sl = ks->seq.l;
        if (has_qual) { prev.qual = malloc(ks->qual.l + 1); memcpy(prev.qual, ks->qual.s, ks->qual.l); prev.qual[ks->qual.l]=0; prev.ql = ks->qual.l; }
        else { prev.qual = NULL; prev.ql = 0; }
    }
    if (prev.name) { free(prev.name); free(prev.comment); free(prev.seq); free(prev.qual); }
    kseq_destroy(ks); gzclose(fp);
    return 0;
}

/* ---------- split ---------- */
static int stk_split(int argc, char **argv) {
    int c;
    int n = 10;
    int line_len = 0;
    optind = 1;
    while ((c = getopt(argc, argv, "n:l:")) >= 0) {
        if (c == 'n') n = atoi(optarg);
        else if (c == 'l') line_len = atoi(optarg);
    }
    if (argc - optind < 2) {
        fprintf(stderr, "Usage: seqtk split [options] <prefix> <in.fa>\n");
        fprintf(stderr, "Options:\n");
        fprintf(stderr, "  -n INT    number of files [10]\n");
        fprintf(stderr, "  -l INT    line length [0]\n");
        return 1;
    }
    const char *prefix = argv[optind];
    const char *fn = argv[optind+1];
    gzFile fp = xzopen(fn);
    if (!fp) { fprintf(stderr, "[E::stk_split] failed to open the input file/stream.\n"); return 1; }
    kseq_t *ks = kseq_init(fp);
    FILE **outs = calloc(n, sizeof(FILE*));
    int is_fq = -1;
    long count = 0;
    while (kseq_read(ks) >= 0) {
        if (is_fq < 0) is_fq = ks->qual.l > 0 ? 1 : 0;
        int idx = count % n;
        if (!outs[idx]) {
