            if (max_score > 0) { start = max_s; end = max_e; }
            if (end - start < min_len) {
                /* keep maximum length window of min_len centered on max quality? original uses different heuristic. */
                if (l <= min_len) { start = 0; end = l; }
                else { start = 0; end = l; }
            }
