static int stk_hety(int argc, char **argv) {
    int c;
    int win = 50000, t = 5, mask_lc = 0;
    optind = 1;
    while ((c = getopt(argc, argv, "w:t:m")) >= 0) {
        if (c == 'w') win = atoi(optarg);
        else if (c == 't') t = atoi(optarg);
        else if (c == 'm') mask_lc = 1;
    }
    if (argc == optind && isatty(fileno(stdin))) {
        fprintf(stderr, "\nUsage:   seqtk hety [options] <in.fa>\n\n");
        fprintf(stderr, "Options: -w INT   window size [50000]\n");
        fprintf(stderr, "         -t INT   # start positions in a window [5]\n");
        fprintf(stderr, "         -m       treat lowercases as masked\n\n");
        return 1;
    }
    gzFile fp = xzopen(argc > optind ? argv[optind] : NULL);
    if (!fp) { fprintf(stderr, "[E::stk_hety] failed to open the input file/stream.\n"); return 1; }
    kseq_t *ks = kseq_init(fp);
    while (kseq_read(ks) >= 0) {
        int l = ks->seq.l;
        /* classify each position: 0=invalid, 1=homo, 2=het */
        char *cls = malloc(l);
        for (int i = 0; i < l; i++) {
            unsigned char b = ks->seq.s[i];
            if (mask_lc && islower(b)) { cls[i] = 0; continue; }
            unsigned char B = toupper(b);
            if (B == 'A' || B == 'C' || B == 'G' || B == 'T' || B == 'U') cls[i] = 1;
            else if (B == 'M' || B == 'R' || B == 'W' || B == 'S' || B == 'Y' || B == 'K' || B == 'B' || B == 'D' || B == 'H' || B == 'V') cls[i] = 2;
            else cls[i] = 0;
        }
        for (int start = 0; start < l; start += win) {
            int end = start + win;
            if (end > l) end = l;
            int nhet = 0, nvalid = 0;
            for (int i = start; i < end; i++) {
                if (cls[i] == 2) nhet++;
                if (cls[i] != 0) nvalid++;
            }
            if (nvalid < t) {
