    to_bits['H'] = to_bits['h'] = 1|2|8;
    to_bits['D'] = to_bits['d'] = 1|4|8;
    to_bits['B'] = to_bits['b'] = 2|4|8;
    to_bits['N'] = to_bits['n'] = 1|2|4|8;
    const char *from_bits = "XACMGRSVTWYHKDBN";

    while (1) {
        int r1 = kseq_read(k1), r2 = kseq_read(k2);
        if (r1 < 0 || r2 < 0) break;
        int l = k1->seq.l < k2->seq.l ? k1->seq.l : k2->seq.l;
        printf(">%s", k1->name.s);
        if (k1->comment.l) { putchar(' '); fwrite(k1->comment.s, 1, k1->comment.l, stdout); }
        putchar('\n');
        char *out = malloc(l + 1);
        int out_l = 0;
        for (int i = 0; i < l; i++) {
            unsigned char a = k1->seq.s[i], b = k2->seq.s[i];
            int ba = to_bits[a], bb = to_bits[b];
            int is_het_a = (__builtin_popcount(ba & 15) == 2);
            int is_het_b = (__builtin_popcount(bb & 15) == 2);
            int is_n_a = (ba == 15 || toupper(a) == 'N');
            int is_n_b = (bb == 15 || toupper(b) == 'N');
            if (is_n_a || is_n_b) {
                if (flag & 1) { /* intersection: skip */ continue; }
                /* default: output whichever isn't N, if both N then N */
                if (is_n_a && is_n_b) out[out_l++] = 'N';
                else if (is_n_a) out[out_l++] = b;
                else out[out_l++] = a;
                continue;
            }
            if (flag & 8) {
                /* suppress hets: if either is het, use the hom one */
                if (is_het_a && is_het_b) {
                    /* both het, use union */
                    int u = ba | bb;
                    out[out_l++] = from_bits[u & 15];
                } else if (is_het_a) {
                    out[out_l++] = b;
                } else if (is_het_b) {
                    out[out_l++] = a;
                } else if (a == b) { out[out_l++] = a; same++; }
                else { out[out_l++] = from_bits[(ba|bb)&15]; diff++; }
                continue;
            }
            if (a == b) { out[out_l++] = a; same++; }
            else {
                if (is_het_a && is_het_b) het_het++;
                else if (is_het_a) hom_het++; /* confusion but track */
                else if (is_het_b) het_hom++;
                else diff++;
                int u = ba | bb;
                char out_c = from_bits[u & 15];
                if (flag & 2) {
                    out_c = tolower((unsigned char)out_c);
                    if (__builtin_popcount(u & 15) >= 2) out_c = 'x';
                }
                out[out_l++] = out_c;
            }
        }
        if (flag & 1) {
            /* intersection mode: don't output sequence, only stats */
        } else {
            fwrite(out, 1, out_l, stdout); putchar('\n');
        }
        free(out);
    }
    fprintf(stderr, "[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=(%d,%d,%d,%d,%d)\n",
            same, diff, hom_het, het_hom, het_het);
    kseq_destroy(k1); kseq_destroy(k2);
    gzclose(f1); gzclose(f2);
    return 0;
}

/* ---------- rename ---------- */
static int stk_rename(int argc, char **argv) {
    const char *prefix = NULL;
    if (argc < 2) { fprintf(stderr, "Usage: seqtk rename <in.fq> [prefix]\n"); return 1; }
    if (argc >= 3) prefix = argv[2];
    gzFile fp = xzopen(argv[1]);
    if (!fp) { fprintf(stderr, "[E::stk_rename] failed to open the input file/stream.\n"); return 1; }
    kseq_t *ks = kseq_init(fp);
    long n = 0;
    while (kseq_read(ks) >= 0) {
        n++;
        int has_qual = ks->qual.l > 0;
        putchar(has_qual ? '@' : '>');
        if (prefix) fputs(prefix, stdout);
        printf("%ld", n);
        if (ks->comment.l) { putchar(' '); fwrite(ks->comment.s, 1, ks->comment.l, stdout); }
        putchar('\n');
        fwrite(ks->seq.s, 1, ks->seq.l, stdout); putchar('\n');
        if (has_qual) { puts("+"); fwrite(ks->qual.s, 1, ks->qual.l, stdout); putchar('\n'); }
    }
    kseq_destroy(ks); gzclose(fp);
    return 0;
}

