/* ---------- cutN ---------- */
static int stk_cutN(int argc, char **argv) {
    int c;
    int min_n = 1000;
    int penalty = 10;
    int gap_only = 0;
    optind = 1;
    while ((c = getopt(argc, argv, "n:p:g")) >= 0) {
        if (c == 'n') min_n = atoi(optarg);
        else if (c == 'p') penalty = atoi(optarg);
        else if (c == 'g') gap_only = 1;
    }
    if (argc == optind && isatty(fileno(stdin))) {
        fprintf(stderr, "\nUsage:   seqtk cutN [options] <in.fa>\n\n");
        fprintf(stderr, "Options: -n INT    min size of N tract [1000]\n");
        fprintf(stderr, "         -p INT    penalty for a non-N [10]\n");
        fprintf(stderr, "         -g        print gaps only, no sequence\n\n");
        return 1;
    }
    gzFile fp = xzopen(argc > optind ? argv[optind] : NULL);
    if (!fp) { fprintf(stderr, "[E::stk_cutN] failed to open the input file/stream.\n"); return 1; }
    kseq_t *ks = kseq_init(fp);
    while (kseq_read(ks) >= 0) {
        int L = ks->seq.l;
        /* Find N tracts using scoring: +1 per N, -penalty per non-N. Track max-scoring intervals. */
        /* Simpler: find maximal intervals where internal non-N count is small. */
        int *is_n = malloc(L);
        for (int i = 0; i < L; i++) is_n[i] = is_any_n(ks->seq.s[i]);
        /* collect intervals */
        typedef struct { int s, e; } iv_t;
        iv_t *ivs = NULL; int nivs = 0, mivs = 0;
        int i = 0;
        while (i < L) {
            if (!is_n[i]) { i++; continue; }
            /* extend run allowing up to penalty -1 non-N in between */
            int s = i;
            int score = 0, maxscore = 0;
            int cur_e = i;
            int best_e = i;
            for (; i < L; i++) {
                if (is_n[i]) score += 1;
                else score -= penalty;
                if (score < 0) break;
                if (score >= maxscore) { maxscore = score; best_e = i + 1; }
                cur_e = i + 1;
            }
            int e = best_e;
            /* count N in [s,e) */
            int nN = 0;
            for (int j = s; j < e; j++) if (is_n[j]) nN++;
            if (nN >= min_n) {
                if (nivs >= mivs) { mivs = mivs ? mivs*2 : 8; ivs = realloc(ivs, mivs*sizeof(iv_t)); }
                ivs[nivs].s = s; ivs[nivs].e = e; nivs++;
            }
            if (cur_e <= s) i = s + 1;
            else i = cur_e;
        }
        if (gap_only) {
            for (int k = 0; k < nivs; k++)
                printf("%s\t%d\t%d\n", ks->name.s, ivs[k].s, ivs[k].e);
        } else {
            /* output segments between gaps */
            int prev = 0;
            for (int k = 0; k <= nivs; k++) {
                int s = prev, e = k < nivs ? ivs[k].s : L;
                if (e > s) {
                    printf(">%s:%d-%d\n", ks->name.s, s+1, e);
                    fwrite(ks->seq.s + s, 1, e - s, stdout);
                    putchar('\n');
                }
                if (k < nivs) prev = ivs[k].e;
            }
        }
        free(is_n); free(ivs);
    }
    kseq_destroy(ks); gzclose(fp);
    return 0;
}

/* ---------- gap ---------- */
static int stk_gap(int argc, char **argv) {
    int c;
    int min_l = 50;
    optind = 1;
    while ((c = getopt(argc, argv, "l:")) >= 0) {
        if (c == 'l') min_l = atoi(optarg);
    }
    if (argc == optind && isatty(fileno(stdin))) {
        fprintf(stderr, "Usage: seqtk gap [-l 50] <in.fa>\n");
        return 1;
    }
    gzFile fp = xzopen(argc > optind ? argv[optind] : NULL);
    if (!fp) { fprintf(stderr, "[E::stk_gap] failed to open the input file/stream.\n"); return 1; }
    kseq_t *ks = kseq_init(fp);
    while (kseq_read(ks) >= 0) {
        int L = ks->seq.l;
        int i = 0;
        while (i < L) {
            if (!is_any_n(ks->seq.s[i])) { i++; continue; }
            int s = i;
            while (i < L && is_any_n(ks->seq.s[i])) i++;
            int e = i;
            if (e - s >= min_l)
                printf("%s\t%d\t%d\n", ks->name.s, s, e);
        }
    }
    kseq_destroy(ks); gzclose(fp);
    return 0;
}

