static int stk_telo(int argc, char **argv) {
    int c;
    const char *motif = "CCCTAA";
    int penalty = 1;
    int max_drop = 2000;
    int min_score = 300;
    int print_scoring = 0;
    optind = 1;
    while ((c = getopt(argc, argv, "m:p:d:s:P")) >= 0) {
        if (c == 'm') motif = optarg;
        else if (c == 'p') penalty = atoi(optarg);
        else if (c == 'd') max_drop = atoi(optarg);
        else if (c == 's') min_score = atoi(optarg);
        else if (c == 'P') print_scoring = 1;
    }
    (void)max_drop; (void)print_scoring;
    gzFile fp = xzopen(argc > optind ? argv[optind] : NULL);
    if (!fp) {
        long long zero = 0;
        printf("%lld\t%lld\n", zero, zero);
        return 0;
    }
    kseq_t *ks = kseq_init(fp);
    long long telo_bp = 0, total_bp = 0;
    int motif_len = strlen(motif);
    /* revcomp of motif */
    char rc_motif[64];
    int mlen = strlen(motif);
    for (int i = 0; i < mlen; i++) rc_motif[i] = comp_tab[(unsigned char)motif[mlen-1-i]];
    rc_motif[mlen] = 0;

    while (kseq_read(ks) >= 0) {
        int L = ks->seq.l;
        total_bp += L;
        /* From 5' end: look for runs of motif; from 3' end: look for rc_motif. */
        /* Find maximum 5' telomere region: starting from position 0, accumulate +1 for motif match, -penalty for mismatch. */
        int best_score = 0, best_e = 0, cur_score = 0;
        int i = 0;
        while (i + motif_len <= L) {
            int match = 1;
            for (int j = 0; j < motif_len; j++) {
                if (toupper((unsigned char)ks->seq.s[i+j]) != toupper((unsigned char)motif[j])) { match = 0; break; }
            }
            if (match) { cur_score += motif_len; i += motif_len; }
            else { cur_score -= penalty; i++; }
            if (cur_score > best_score) { best_score = cur_score; best_e = i; }
            if (cur_score < 0) cur_score = 0;
        }
        int five_end = (best_score >= min_score) ? best_e : 0;

        /* 3' end: look for rc_motif in reverse */
        best_score = 0; cur_score = 0;
        int best_s = L;
        i = L;
        while (i - motif_len >= 0) {
            int match = 1;
            for (int j = 0; j < motif_len; j++) {
                if (toupper((unsigned char)ks->seq.s[i-motif_len+j]) != toupper((unsigned char)rc_motif[j])) { match = 0; break; }
            }
            if (match) { cur_score += motif_len; i -= motif_len; }
            else { cur_score -= penalty; i--; }
            if (cur_score > best_score) { best_score = cur_score; best_s = i; }
            if (cur_score < 0) cur_score = 0;
        }
        int three_start = (best_score >= min_score) ? best_s : L;

        if (five_end > 0) {
            printf("%s\t0\t%d\t%d\n", ks->name.s, five_end, L);
            telo_bp += five_end;
        }
        if (three_start < L) {
            printf("%s\t%d\t%d\t%d\n", ks->name.s, three_start, L, L);
            telo_bp += L - three_start;
        }
    }
    fprintf(stderr, "%lld\t%lld\n", telo_bp, total_bp);
    kseq_destroy(ks); gzclose(fp);
    (void)penalty;
    return 0;
}

