                    out_c = tolower(from_bits[u & 15]);
                } else {
                    out_c = from_bits[u & 15];
                }
            } else if (is_het_a) {
                het_hom++;
                /* if b's base is one of a's alleles */
                if (ba & bb) out_c = b;
                else out_c = tolower(from_bits[(ba|bb)&15]);
            } else if (is_het_b) {
                hom_het++;
                if (ba & bb) out_c = a;
                else out_c = tolower(from_bits[(ba|bb)&15]);
            } else if (a == b) {
                same++;
                out_c = a;
            } else {
                diff++;
                out_c = from_bits[(ba|bb)&15];
            }
            putchar(out_c);
        }
        putchar('\\n');
    }
    fprintf(stderr, "[stk_mergefa] (same,diff,hom-het,het-hom,het-het)=(%d,%d,%d,%d,%d)\\n",
            same, diff, hom_het, het_hom, het_het);
    kseq_destroy(k1); kseq_destroy(k2);
    gzclose(f1); gzclose(f2);
    return 0;
}

